import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int p = scanner.nextInt();
        int k = scanner.nextInt();
        final long MOD = 1000000007L;
        long finalAnswer = 0;

        if (k == 0) {
            finalAnswer = binaryExponentiation(p, p - 1, MOD);
        } else {
            for (int i = 1; i < p; i++) {
                if ((p - 1) % i == 0 && binaryExponentiation(k, i, p) == 1) {
                    finalAnswer = binaryExponentiation(p, (p - 1) / i, MOD);
                    if (k == 1) {
                        finalAnswer = (finalAnswer * p) % MOD;
                    }
                    break;
                }
            }
        }
        System.out.println(finalAnswer);
    }

    private static long binaryExponentiation(long base, long exponent, long modulus) {
        long result = 1;
        base = base % modulus;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % modulus;
            }
            base = (base * base) % modulus;
            exponent >>= 1;
        }
        return result;
    }
}

